// Nothing uses `late`, and awaiting here has no effect of its own, so the
// package's sideEffects declaration is true. Node still treats this module
// as asynchronous, so the barrel and first.ts start only after it settles
// and second.ts runs before first.ts. Skipping the module would let
// first.ts run before second.ts.
await Promise.resolve();

export const late = 1;
